            continue
        max_age = governing_max_age(path, policies)
        if max_age is not None and age_days > max_age:
            delete.add(path)
    return delete", "new": "def plan_deletions(files, policies) -> set:
    """Return the set of paths that should be deleted.

    If the same path appears more than once (e.g. conflicting records),
    we are conservative: any hold on any record protects the path, and
    every record for the path must be strictly older than its governing
    max_age before the path may be deleted.
    """
    by_path = {}
    for path, age_days, held in files:
        holds, ages = by_path.get(path, (False, []))
        by_path[path] = (holds or held, ages + [age_days])

    delete = set()
    for path, (held, ages) in by_path.items():
        if held:
            continue
        max_age = governing_max_age(path, policies)
        if max_age is not None and min(ages) > max_age:
            delete.add(path)
    return delete"}]})
